package com.fasterxml.jackson.databind.cfg;

import com.fasterxml.jackson.annotation.JsonAutoDetect;
import com.fasterxml.jackson.annotation.PropertyAccessor;
import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.io.Base64Variant;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.BaseSettings;
import com.fasterxml.jackson.databind.cfg.HandlerInstantiator;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.introspect.ClassIntrospector;
import com.fasterxml.jackson.databind.introspect.VisibilityChecker;
import com.fasterxml.jackson.databind.jsontype.TypeResolverBuilder;
import com.fasterxml.jackson.databind.ser.PropertyNamingStrategy;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.type.TypeResolverBuilder;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;

public class BaseSettings_withDateFormat_TriageGen0Test {

    private ClassIntrospector _classIntrospector;
    private AnnotationIntrospector _annotationIntrospector;
    private VisibilityChecker<?> _visibilityChecker;
    private PropertyNamingStrategy _propertyNamingStrategy;
    private TypeFactory _typeFactory;
    private TypeResolverBuilder<?> _typeResolverBuilder;
    private HandlerInstantiator _handlerInstantiator;
    private Locale _locale;
    private TimeZone _timeZone;
    private Base64Variant _defaultBase64;
    private BaseSettings _baseSettings;

    @Before
    public void setUp() {
        _classIntrospector = null; // Using nulls or mocks is fine for coverage of the constructor call
        _annotationIntrospector = null;
        _visibilityChecker = null;
        _propertyNamingStrategy = null;
        _typeFactory = null;
        _typeResolverBuilder = null;
        _handlerInstantiator = null;
        _locale = Locale.US;
        _timeZone = TimeZone.getDefault();
        _defaultBase64 = Base64Variant.of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/");

        // Initialize a base settings object
        _baseSettings = new BaseSettings(
                _classIntrospector, _annotationIntrospector, _visibilityChecker, _propertyNamingStrategy, _typeFactory,
                _typeResolverBuilder, null, _handlerInstantiator, _locale, _timeZone, _defaultBase64
        );
    }

    @Test
    public void testWithDateFormat_SameInstance() {
        DateFormat df = new SimpleDateFormat("yyyy-MM-dd");
        // Set the current date format to match to trigger the (df == _dateFormat) branch
        BaseSettings settingsWithDf = _baseSettings.withDateFormat(df);

        // We need to ensure the internal _dateFormat is actually df. 
        // Since we can't set it directly, we use the method to create a state where they are equal.
        BaseSettings initial = _baseSettings.withDateFormat(df);
        BaseSettings result = initial.withDateFormat(df);

        assertSame("Should return the same instance if DateFormat is identical", initial, result);
    }

    @Test
    public void testWithDateFormat_NewInstanceWithDateFormat() {
        DateFormat df = new SimpleDateFormat("yyyy-MM-dd");
        TimeZone expectedTz = df.getTimeZone();

        BaseSettings result = _baseSettings.withDateFormat(df);

        assertNotSame("Should return a new instance when DateFormat is different", _baseSettings, result);
        assertEquals("New DateFormat should match the provided one", df, result.getDateFormat());
        assertEquals("TimeZone should be extracted from the new DateFormat", expectedTz, result.getTimeZone());
        assertEquals("Other properties should remain consistent", _locale, result.getLocale());
    }

    @Test
    public void testWithDateFormat_NullDateFormatUsesExistingTimeZone() {
        // Current settings have _timeZone set in setUp
        TimeZone originalTz = _baseSettings.getTimeZone();

        BaseSettings result = _baseSettings.withDateFormat(null);

        assertNotSame("Should return a new instance when passing null", _baseSettings, result);
        assertEquals("DateFormat should be null", null, result.getDateFormat());
        assertEquals("TimeZone should be preserved from the original settings when df is null", originalTz, result.getTimeZone());
    }
}
